SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for base_area
-- ----------------------------
DROP TABLE IF EXISTS `base_area`;
CREATE TABLE `base_area`  (
  `SID` bigint(0) NOT NULL COMMENT '主键',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '应用ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '区域名称',
  `ALIAS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '区域别名',
  `EN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '英文',
  `SN` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `LNG` double NULL DEFAULT NULL COMMENT '经度',
  `LAT` double NULL DEFAULT NULL COMMENT '维度',
  `ADDRESS` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '地址',
  `LEVEL` int(0) NOT NULL COMMENT '级别(0=国家&1=省&2=市&3=区&4=县&5=街道&6=居委会)',
  `ORDERED` smallint(0) NULL DEFAULT NULL COMMENT '排序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '是否有效1 是，0 否',
  `IS_LEAF` int(0) NULL DEFAULT NULL COMMENT '是否叶子节点，字典TUREORFALSE 1是，0否',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`SID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '基础：区域' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of base_area
-- ----------------------------

-- ----------------------------
-- Table structure for base_dict
-- ----------------------------
DROP TABLE IF EXISTS `base_dict`;
CREATE TABLE `base_dict`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '应用ID',
  `APP_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用名称',
  `DICT_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字典名称',
  `DICT_TYPE` int(0) NOT NULL COMMENT '字典类型，1平台，2租户，3机构',
  `DICT_KEY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字典键',
  `DICT_VALUE` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '字典值',
  `DICT_SHOW` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '字典显示设置，json存储{}',
  `ORDERED` smallint(0) NOT NULL COMMENT '排序',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典TUREORFALSE 1是，0否',
  `STATUS` int(0) NOT NULL COMMENT '状态 是否使用，字典USEORNOT 1 使用，0停用',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '基础：字典' ROW_FORMAT = Dynamic;

