-- ----------------------------
-- Table structure for base_dict_setting
-- ----------------------------
DROP TABLE IF EXISTS `base_dict_setting`;
CREATE TABLE `base_dict_setting`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `DICT_ID` bigint(0) NOT NULL COMMENT '字典ID',
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '应用ID',
  `APP_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用名称',
  `DICT_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字典名称',
  `DICT_TYPE` int(0) NOT NULL COMMENT '字典类型，1平台，2租户，3机构',
  `DICT_KEY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字典键',
  `DICT_VALUE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字典值',
  `DICT_SHOW` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '字典显示设置，json存储{}',
  `ORDERED` int(0) NOT NULL COMMENT '排序',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典TUREORFALSE 1是，0否',
  `STATUS` int(0) NOT NULL COMMENT '状态 是否使用，字典USEORNOT 1 使用，0停用',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '基础：字典设置，租户，机构字典设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of base_dict_setting
-- ----------------------------

-- ----------------------------
-- Table structure for base_trade
-- ----------------------------
DROP TABLE IF EXISTS `base_trade`;
CREATE TABLE `base_trade`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `PARENT_ID` bigint(0) NULL DEFAULT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '所属租户',
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '所属应用',
  `NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '行业分类名称',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '行业代码',
  `LEVEL` int(0) NOT NULL COMMENT '行业级别',
  `REMARK` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行业描述',
  `STATUS` int(0) NOT NULL COMMENT '是否有效1 是，0 否',
  `CREATED` timestamp(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` timestamp(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '基础：行业分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of base_trade
-- ----------------------------

-- ----------------------------
-- Table structure for comm_visit_item
-- ----------------------------
DROP TABLE IF EXISTS `comm_visit_item`;
CREATE TABLE `comm_visit_item`  (
  `ID` bigint(0) NOT NULL,
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID/站点id',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID，-1：匿名',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID，-1：匿名',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID，-1：匿名',
  `TARGET_ID` bigint(0) NOT NULL COMMENT '目标ID',
  `EXPLORER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '浏览器',
  `OSNAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作系统',
  `VISIT_TIME` datetime(0) NOT NULL COMMENT '访问时间',
  `VISIT_YEAR` int(0) NOT NULL COMMENT '访问年份',
  `VISIT_QUAR` int(0) NOT NULL COMMENT '访问季度',
  `VISIT_MONTH` int(0) NOT NULL COMMENT '访问月份',
  `VISIT_WEEK` int(0) NOT NULL COMMENT '访问周',
  `VISIT_DAY` int(0) NOT NULL COMMENT '访问日',
  `VISIT_IP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '访问IP',
  `COUNTRY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在国家',
  `PROVINCE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在省份',
  `CITY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在城市',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`TARGET_ID`, `VISIT_TIME`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '通用：访问登记-明细' ROW_FORMAT = Dynamic;

