-- ----------------------------
-- Table structure for comm_visit_stat
-- ----------------------------
DROP TABLE IF EXISTS `comm_visit_stat`;
CREATE TABLE `comm_visit_stat`  (
  `ID` bigint(0) NOT NULL,
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID/站点id',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID，-1：匿名',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID，-1：匿名',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID，-1：匿名',
  `TARGET_ID` bigint(0) NOT NULL COMMENT '目标ID',
  `EXPLORER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '浏览器',
  `OSNAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作系统',
  `VISIT_DATE` date NOT NULL COMMENT '访问日期',
  `VISIT_YEAR` int(0) NOT NULL COMMENT '访问年份',
  `VISIT_QUAR` int(0) NOT NULL COMMENT '访问季度',
  `VISIT_MONTH` int(0) NOT NULL COMMENT '访问月份',
  `VISIT_WEEK` int(0) NOT NULL COMMENT '访问周',
  `VISIT_DAY` int(0) NOT NULL COMMENT '访问日',
  `VISIT_COUNT` int(0) NOT NULL COMMENT '访问数量',
  `COUNTRY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在国家',
  `PROVINCE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在省份',
  `CITY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所在城市',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`VISIT_DATE`, `APP_ID`, `TARGET_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '通用：访问登记-统计' ROW_FORMAT = Dynamic;

