-- ----------------------------
-- Table structure for comm_visit_target
-- ----------------------------
DROP TABLE IF EXISTS `comm_visit_target`;
CREATE TABLE `comm_visit_target`  (
  `ID` bigint(0) NOT NULL,
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '应用ID/站点ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `TARGET_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '目标类型，字典COMMVISITTARGETTYPE menu：菜单页面，site：网站页面',
  `TARGET_TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '目标标题',
  `TARGET_ID` bigint(0) NULL DEFAULT NULL COMMENT '目标ID',
  `TARGET_URL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '目标url',
  `COVER` bigint(0) NULL DEFAULT NULL COMMENT '封面图片id',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '通用：访问登记-目标' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of comm_visit_target
-- ----------------------------
INSERT INTO `comm_visit_target` VALUES (1951271768050290688, 1, -1, NULL, NULL, NULL, 'menu', '测试', 10, '/Test', NULL, 0, NULL, 1, 0, '2025-08-01 21:20:17', NULL, '2025-08-01 21:20:17', NULL);

-- ----------------------------
-- Table structure for doc_dir
-- ----------------------------
DROP TABLE IF EXISTS `doc_dir`;
CREATE TABLE `doc_dir`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `PARENT_ID` bigint(0) NULL DEFAULT NULL COMMENT '上级目录ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `APP_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '应用编码',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '名称',
  `PWD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '目录密码',
  `TYPE` int(0) NULL DEFAULT NULL COMMENT '类型 字典DOCDIRTYPE ',
  `ICON_PIC` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标文件url',
  `BUSY_KEY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务KEY,在某些业务场景下进行业务隔离',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `IS_SHOW` int(0) NULL DEFAULT NULL COMMENT '显示状态：1:显示,2:隐藏',
  `IS_PUBLIC` int(0) NULL DEFAULT NULL COMMENT '公开状态：0:不公开,1:公开',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `DEL_FLAG` int(0) NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '文档管理：文档目录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of doc_dir
-- ----------------------------

-- ----------------------------
-- Table structure for doc_file
-- ----------------------------
DROP TABLE IF EXISTS `doc_file`;
CREATE TABLE `doc_file`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `DIR_ID` bigint(0) NULL DEFAULT NULL COMMENT '文档目录ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `OWNER_ID` bigint(0) NULL DEFAULT NULL COMMENT '附件所有者ID',
  `APP_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '应用编码',
  `TITLE` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '附件标题',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '附件名称（表单中的名称）',
  `SIZE` float NULL DEFAULT NULL COMMENT '附件大小(字节)',
  `TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '附件类型:jpg,doc,png',
  `PATH` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '附件路径',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '附件状态',
  `IS_PUBLIC` int(0) NULL DEFAULT NULL COMMENT '公开状态：0:不公开,1:公开',
  `AUDIT_STATUS` int(0) NULL DEFAULT NULL COMMENT '审核状态，公开或共享时的审核状态，字典DOCFILEAUDITSTS 1待审，2通过，3拒绝',
  `EXT_DATA` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '扩展信息，json存储{}',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `DEL_FLAG` int(0) NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '文档管理：文档信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of doc_file
-- ----------------------------

-- ----------------------------
-- Table structure for doc_permis
-- ----------------------------
DROP TABLE IF EXISTS `doc_permis`;
CREATE TABLE `doc_permis`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `FILE_ID` bigint(0) NULL DEFAULT NULL COMMENT '文档ID',
  `FILE_TITLE` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '文件标题',
  `FILE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '文件名称',
  `FILE_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '文件类型',
  `LIST` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '权限集合，[view,dowland]',
  `OWNER_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '权限拥有者类别,字典DOCPERMISTYPE user：用户，role：角色，org：机构，public：公开',
  `OWNER_ID` bigint(0) NULL DEFAULT NULL COMMENT '权限拥有者ID',
  `OWNER_TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '权限拥有者标题',
  `AUDIT_TYPE` int(0) NULL DEFAULT NULL COMMENT '审核类型，字典DOCAUDITTYPE 1公开审核，2共享审核',
  `AUDIT_USERID` bigint(0) NULL DEFAULT NULL COMMENT '审核人员ID',
  `AUDIT_USERNAME` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '审核人员姓名',
  `AUDIT_RESULT` int(0) NULL DEFAULT NULL COMMENT '审核结果 字典DOCFILEAUDITSTS 1待审，2通过，3拒绝',
  `AUDIT_OPINION` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '审核说明',
  `AUDIT_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '审核时间',
  `DEL_FLAG` int(0) NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '文档管理：文档权限' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of doc_permis
-- ----------------------------

-- ----------------------------
-- Table structure for sys_api_info
-- ----------------------------
DROP TABLE IF EXISTS `sys_api_info`;
CREATE TABLE `sys_api_info`  (
  `ID` bigint(0) NOT NULL,
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID(根节点为-1)',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '名称（英文名称，一个应用中保持唯一）',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'URL地址,/开头，不包含应用ctx',
  `METHOD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '请求方式，多个用逗号 \'\',\'\' 分隔。字典 REQUESTMETHOD:POST,GET,PUT,DELETE,PATCH,OPTIONS,HEAD',
  `PARAMS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '请求参数',
  `RESPONSE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '接口响应',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典 TUREORFALSE 1是，0否',
  `IS_NEED_PERMIS` int(0) NOT NULL COMMENT '是否需要授权，字典 TUREORFALSE 1是，0否',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `DOC_BODY` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '文档内容',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`, `CREATED`, `CREATED_BY`, `LAST_UPDATED`, `LAST_UPDATED_BY`) USING BTREE,
  UNIQUE INDEX `APP_NAME`(`APP_ID`, `NAME`) USING BTREE,
  INDEX `PARENT_ID`(`PARENT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：接口信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_api_info
-- ----------------------------

-- ----------------------------
-- Table structure for sys_app_info
-- ----------------------------
DROP TABLE IF EXISTS `sys_app_info`;
CREATE TABLE `sys_app_info`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用名称',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用编码，唯一',
  `IS_MP` int(0) NOT NULL COMMENT '是否微应用',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用URL',
  `WELCOME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '首页URL',
  `VERS_NO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '版本号',
  `VERS_DESC` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '版本说明',
  `ICON` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `TRADES` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行业分类，多个逗号分隔',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资源发布，字典APPTYPES pc：PC，app：APP',
  `IS_PLATFORM` int(0) NOT NULL COMMENT '是否平台应用，字典 TUREORFALSE 1是，0否',
  `IS_TMPL` int(0) NOT NULL COMMENT '是否模版，字典 TUREORFALSE 1是，0否',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1新建，2内测，3发布，4撤销',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN`(`SN`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：应用信息' ROW_FORMAT = Dynamic;

