-- ----------------------------
-- Table structure for sys_config_define
-- ----------------------------
DROP TABLE IF EXISTS `sys_config_define`;
CREATE TABLE `sys_config_define`  (
  `ID` bigint(0) NOT NULL,
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `APP_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应用名称',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '名称',
  `SN` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '配置编码，从配置根节点的NAM逐层拼接到当前配置NAME,使用“.”分割',
  `TYPES` int(0) NOT NULL COMMENT '类型，字典IUCONFTYPE 0全局，1租户级，2机构级，3用户级',
  `VALUE_DEFAULT` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '默认值',
  `VALUE_USED` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '设置值',
  `LVSN` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '层级编码',
  `LEVEL` int(0) NOT NULL COMMENT '所在层级',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `IS_AUTH` int(0) NOT NULL COMMENT '是否需要授权，字典TUREORFALSE 1是，0否，对于非平台的配置，如果设置成需要权限，则没有权限的帐号不能进行配置操作',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN_NUI`(`SN`) USING BTREE,
  INDEX `CONFG_SN_APP_MODEL`(`SN`, `APP_ID`) USING BTREE,
  INDEX `LVSN`(`LVSN`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：统一配置' ROW_FORMAT = Dynamic;

