-- ----------------------------
-- Table structure for sys_data_auth
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_auth`;
CREATE TABLE `sys_data_auth`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DEFINE_ID` bigint(0) NOT NULL COMMENT '数据定义ID',
  `PERMIS_ID` bigint(0) NOT NULL COMMENT '数据权限ID',
  `TARGET_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '目标类型，字典DMSDATAAUTHTYPE  dc：中心， role：角色，user：用户，organ：机构',
  `TARGET_ID` bigint(0) NOT NULL COMMENT '目标ID',
  `STATUS` int(0) NOT NULL COMMENT '使用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据授权' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_auth
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_convertor
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_convertor`;
CREATE TABLE `sys_data_convertor`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DS_ID` bigint(0) NULL DEFAULT NULL COMMENT '数据源ID',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标题',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '类型，dict：字典，option：静态选项，dbtable：数据集，api：接口',
  `DICT_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '字典名称',
  `OPTIONS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '静态选项',
  `SEARCH` tinyint(1) NULL DEFAULT NULL COMMENT '搜索是否可用',
  `URL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '接口url地址',
  `TABLE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'table名称',
  `TABLE_FIELD` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '数据字段集合',
  `TABLE_WHERE` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '数据过滤',
  `TABLE_ORDER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '数据排序',
  `ID_FIELD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '主键字段，默认ID',
  `PID_FIELD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '父级字段，默认PID',
  `VALUE_FIELD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'value字段',
  `LABEL_FIELD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'label字段',
  `SHOW_LEVEL` int(0) NULL DEFAULT NULL COMMENT '显示层级',
  `IS_ASYNC` tinyint(1) NULL DEFAULT NULL COMMENT '是否异步，树形结构是否异步加载',
  `IS_PAGING` tinyint(1) NULL DEFAULT NULL COMMENT '是否分页，是否分页加载',
  `STATUS` int(0) NOT NULL COMMENT '使用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据转换器' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_convertor
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_define
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_define`;
CREATE TABLE `sys_data_define`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DIR_ID` bigint(0) NULL DEFAULT NULL COMMENT '目录ID',
  `DS_ID` bigint(0) NULL DEFAULT NULL COMMENT '数据源ID',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数据标题',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数据名称，对应数据库表名称',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数据编码',
  `VERS` int(0) NOT NULL COMMENT '版本号',
  `CATEGORY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类别，sql：关系型存储，nosql：非关系型存储，api：接口存储',
  `URL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'URL，api接口url，不包含服务ctx部分,/开头，eg：/user',
  `IS_CUSTOM` int(0) NULL DEFAULT NULL COMMENT '自定义，字典TUREORFALSE 1是，0否',
  `PUBLISH_DATE` timestamp(0) NULL DEFAULT NULL COMMENT '发布日期',
  `FIND_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '数据查询脚本',
  `INSERT_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '数据新增脚本',
  `UPDATE_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '数据更新脚本',
  `DELETE_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '数据删除脚本',
  `SYNC_FLAG` int(0) NOT NULL COMMENT '同步状态，是否已同步数据库，字典TUREORFALSE 1是，0否',
  `CONFIGS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数据配置，json存储,{}',
  `SIGNATURE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '数据签名，（configs，xxxxScript等）字段hash运算后的值',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '发布状态，字典PUBLISHSTATUS 0新建，1提交，2发布，3撤回',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNI_SN`(`SN`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_define
-- ----------------------------
INSERT INTO `sys_data_define` VALUES (1872260963993440256, 100, 1000, NULL, 1, '用户信息', 'sys_user', 'BKnfPiUUKI53oYc3AWd0', 1, 'sql', NULL, 0, '2025-01-02 22:47:59', 'select #{page(\'*\')} from sys_user where 1=1 \n\n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}\n-- @if(isNotEmpty(params.lastUpdatedStart)){\n AND LAST_UPDATED > #{params.lastUpdatedStart}\n-- @}\n-- @if(isNotEmpty(params.lastUpdatedEnd)){\n AND LAST_UPDATED <= #{params.lastUpdatedEnd}\n-- @}\n-- @if(isNotEmpty(params.createdStart)){\n AND CREATED > #{params.createdStart}\n-- @}\n-- @if(isNotEmpty(params.createdEnd)){\n AND CREATED <= #{params.createdEnd}\n-- @}\n-- @if(isNotEmpty(params.delFlag)){\n AND DEL_FLAG=#{params.delFlag}\n-- @}\n-- @if(isNotEmpty(params.userType)){\n AND USER_TYPE=#{params.userType}\n-- @}\n-- @if(isNotEmpty(params.username)){\n AND USERNAME LIKE #{\'%\'+params.username+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.realName)){\n AND REAL_NAME LIKE #{\'%\'+params.realName+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.aliasName)){\n AND ALIAS_NAME=#{params.aliasName}\n-- @}\n-- @if(isNotEmpty(params.sex)){\n AND SEX=#{params.sex}\n-- @}\n-- @if(isNotEmpty(params.tel)){\n AND TEL LIKE #{\'%\'+params.tel+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.status)){\n AND STATUS=#{params.status}\n-- @}\n-- @if(isNotEmpty(params.keywords) && !isBlank(params.keywords)){\n AND (USERNAME LIKE #{\'%\'+params.keywords+\'%\'} OR REAL_NAME LIKE #{\'%\'+params.keywords+\'%\'} OR TEL LIKE #{\'%\'+params.keywords+\'%\'})\n-- @}\n #{globalUse(\"base.orderby\")}', 'insert into sys_user(ID,TENANT_ID,ORG_ID,USER_TYPE,USERNAME,PWD_TEXT,PWD_SALT,REAL_NAME,ALIAS_NAME,AVATAR,BIRTHDAY,SEX,EMAIL,QQ,TEL,SECURITY_QUESTION,SUCURITY_MFA,LAST_LOGIN_TIME,LAST_LOGIN_IP,TOTAL_LOGIN_SUCCESS,TOTAL_LOGIN_FAILUE,STATUS,AUDIT_STS,DEL_FLAG,LOCK_TIME,DESCS,CREATED,CREATED_BY,LAST_UPDATED,LAST_UPDATED_BY) values (#{data.id},#{data.tenantId},#{data.orgId},#{data.userType},#{data.username},#{data.pwdText},#{data.pwdSalt},#{data.realName},#{data.aliasName},#{data.avatar},#{data.birthday},#{data.sex},#{data.email},#{data.qq},#{data.tel},#{data.securityQuestion},#{data.sucurityMfa},#{data.lastLoginTime},#{data.lastLoginIp},#{data.totalLoginSuccess},#{data.totalLoginFailue},#{data.status},#{data.auditSts},#{data.delFlag},#{data.lockTime},#{data.descs},#{data.created},#{data.createdBy},#{data.lastUpdated},#{data.lastUpdatedBy})', 'update sys_user set \n-- @trim(){\n-- @if(isNotEmpty(fields.tenantId)){\nTENANT_ID=#{data.tenantId},\n-- @}\n-- @if(isNotEmpty(fields.orgId)){\nORG_ID=#{data.orgId},\n-- @}\n-- @if(isNotEmpty(fields.userType)){\nUSER_TYPE=#{data.userType},\n-- @}\n-- @if(isNotEmpty(fields.username)){\nUSERNAME=#{data.username},\n-- @}\n-- @if(isNotEmpty(fields.pwdText)){\nPWD_TEXT=#{data.pwdText},\n-- @}\n-- @if(isNotEmpty(fields.pwdSalt)){\nPWD_SALT=#{data.pwdSalt},\n-- @}\n-- @if(isNotEmpty(fields.realName)){\nREAL_NAME=#{data.realName},\n-- @}\n-- @if(isNotEmpty(fields.aliasName)){\nALIAS_NAME=#{data.aliasName},\n-- @}\n-- @if(isNotEmpty(fields.avatar)){\nAVATAR=#{data.avatar},\n-- @}\n-- @if(isNotEmpty(fields.birthday)){\nBIRTHDAY=#{data.birthday},\n-- @}\n-- @if(isNotEmpty(fields.sex)){\nSEX=#{data.sex},\n-- @}\n-- @if(isNotEmpty(fields.email)){\nEMAIL=#{data.email},\n-- @}\n-- @if(isNotEmpty(fields.qq)){\nQQ=#{data.qq},\n-- @}\n-- @if(isNotEmpty(fields.tel)){\nTEL=#{data.tel},\n-- @}\n-- @if(isNotEmpty(fields.securityQuestion)){\nSECURITY_QUESTION=#{data.securityQuestion},\n-- @}\n-- @if(isNotEmpty(fields.sucurityMfa)){\nSUCURITY_MFA=#{data.sucurityMfa},\n-- @}\n-- @if(isNotEmpty(fields.lastLoginTime)){\nLAST_LOGIN_TIME=#{data.lastLoginTime},\n-- @}\n-- @if(isNotEmpty(fields.lastLoginIp)){\nLAST_LOGIN_IP=#{data.lastLoginIp},\n-- @}\n-- @if(isNotEmpty(fields.totalLoginSuccess)){\nTOTAL_LOGIN_SUCCESS=#{data.totalLoginSuccess},\n-- @}\n-- @if(isNotEmpty(fields.totalLoginFailue)){\nTOTAL_LOGIN_FAILUE=#{data.totalLoginFailue},\n-- @}\n-- @if(isNotEmpty(fields.status)){\nSTATUS=#{data.status},\n-- @}\n-- @if(isNotEmpty(fields.auditSts)){\nAUDIT_STS=#{data.auditSts},\n-- @}\n-- @if(isNotEmpty(fields.delFlag)){\nDEL_FLAG=#{data.delFlag},\n-- @}\n-- @if(isNotEmpty(fields.lockTime)){\nLOCK_TIME=#{data.lockTime},\n-- @}\n-- @if(isNotEmpty(fields.descs)){\nDESCS=#{data.descs},\n-- @}\n-- @if(isNotEmpty(fields.created)){\nCREATED=#{data.created},\n-- @}\n-- @if(isNotEmpty(fields.createdBy)){\nCREATED_BY=#{data.createdBy},\n-- @}\n-- @if(isNotEmpty(fields.lastUpdated)){\nLAST_UPDATED=#{data.lastUpdated},\n-- @}\n-- @if(isNotEmpty(fields.lastUpdatedBy)){\nLAST_UPDATED_BY=#{data.lastUpdatedBy},\n-- @}\n-- @}\n where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}', 'UPDATE sys_user SET DEL_FLAG=1 ,LAST_UPDATED=#{data.lastUpdated},LAST_UPDATED_BY=#{data.lastUpdatedBy} where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}', 0, '{\"fields\":[{\"configDto\":{},\"alias\":\"id\",\"appId\":1000,\"defineId\":1872260963993440256,\"title\":\"ID\",\"name\":\"ID\",\"dataType\":\"Long\",\"dataLen\":19,\"isPk\":1,\"isNull\":0,\"configs\":\"{}\",\"needAuth\":0,\"syncEnable\":0,\"syncFlag\":0,\"ordered\":1,\"status\":1,\"id\":1872260964928770048,\"tenantId\":100,\"orgId\":1,\"userId\":10000,\"delFlag\":0,\"created\":1735216773000,\"createdBy\":10000,\"lastUpdated\":1735216773000,\"lastUpdatedBy\":10000},{\"configDto\":{},\"alias\":\"tenantId\",\"appId\":1000,\"defineId\":1872260963993440256,\"title\":\"租户ID\",\"name\":\"TENANT_ID\",\"dataType\":\"Long\",\"dataLen\":19,\"isPk\":0,\"isNull\":0,\"configs\":\"{}\",\"needAuth\":0,\"syncEnable\":0,\"syncFlag\":0,\"ordered\":2,\"status\":1,\"descs\":\"租户ID\",\"id\":1872260964928770049,\"tenantId\":100,\"orgId\":1,\"userId\":10000,\"delFlag\":0,\"created\":1735216773000,\"c