types},#{data.status},#{data.targetId},#{data.startTime},#{data.endTime},#{data.ip},#{data.extData},#{data.errorMessage},#{data.errorCode},#{data.created},#{data.createdBy})', 'update sys_logs set \n-- @trim(){\n-- @if(isNotEmpty(fields.appSn)){\nAPP_SN=#{data.appSn},\n-- @}\n-- @if(isNotEmpty(fields.tenantId)){\nTENANT_ID=#{data.tenantId},\n-- @}\n-- @if(isNotEmpty(fields.orgId)){\nORG_ID=#{data.orgId},\n-- @}\n-- @if(isNotEmpty(fields.userId)){\nUSER_ID=#{data.userId},\n-- @}\n-- @if(isNotEmpty(fields.userName)){\nUSER_NAME=#{data.userName},\n-- @}\n-- @if(isNotEmpty(fields.actionId)){\nACTION_ID=#{data.actionId},\n-- @}\n-- @if(isNotEmpty(fields.requestId)){\nREQUEST_ID=#{data.requestId},\n-- @}\n-- @if(isNotEmpty(fields.prequestId)){\nPREQUEST_ID=#{data.prequestId},\n-- @}\n-- @if(isNotEmpty(fields.title)){\nTITLE=#{data.title},\n-- @}\n-- @if(isNotEmpty(fields.contents)){\nCONTENTS=#{data.contents},\n-- @}\n-- @if(isNotEmpty(fields.types)){\nTYPES=#{data.types},\n-- @}\n-- @if(isNotEmpty(fields.status)){\nSTATUS=#{data.status},\n-- @}\n-- @if(isNotEmpty(fields.targetId)){\nTARGET_ID=#{data.targetId},\n-- @}\n-- @if(isNotEmpty(fields.startTime)){\nSTART_TIME=#{data.startTime},\n-- @}\n-- @if(isNotEmpty(fields.endTime)){\nEND_TIME=#{data.endTime},\n-- @}\n-- @if(isNotEmpty(fields.ip)){\nIP=#{data.ip},\n-- @}\n-- @if(isNotEmpty(fields.extData)){\nEXT_DATA=#{data.extData},\n-- @}\n-- @if(isNotEmpty(fields.errorMessage)){\nERROR_MESSAGE=#{data.errorMessage},\n-- @}\n-- @if(isNotEmpty(fields.errorCode)){\nERROR_CODE=#{data.errorCode},\n-- @}\n-- @if(isNotEmpty(fields.created)){\nCREATED=#{data.created},\n-- @}\n-- @if(isNotEmpty(fields.createdBy)){\nCREATED_BY=#{data.createdBy},\n-- @}\n-- @}\n where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}', 'DELETE FROM sys_logs where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\