-- ----------------------------
-- Table structure for sys_data_permis
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_permis`;
CREATE TABLE `sys_data_permis`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DEFINE_ID` bigint(0) NOT NULL COMMENT '数据定义ID',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '权限名称',
  `NEED_AUTH` int(0) NOT NULL COMMENT '是否需要授权',
  `EXPRESS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '权限SQL表达式',
  `CONFIGS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '权限配置，json存储{}',
  `DESCS` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '权限描述',
  `STATUS` int(0) NOT NULL COMMENT '使用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据权限' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_permis
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_source
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_source`;
CREATE TABLE `sys_data_source`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '名称，eg：数据库名称',
  `CATEGORY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类别，sql：关系型存储，nosql：非关系型存储，api：接口存储',
  `DS_TYPE` int(0) NOT NULL COMMENT '类型 字典 DMSDSTYPE ，1mysql，2oracle，3SqlServer，4SqlServer2005，5达梦，6postgreSql\r\n            说明：1-20关系型数据源，21-40noSql数据源，41-50接口型数据源',
  `IP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'IP',
  `PORT` int(0) NULL DEFAULT NULL COMMENT '端口',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '链接URL',
  `AUTH_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '认证类型，字典DMSDSAUTHTYPE  uname：帐号密码，token：令牌，md5:MD5，auth2:Auth2.0',
  `AUTH_OPTS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '认证选项,json存储{}',
  `DRIVER_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '驱动名称',
  `USERNAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '账号',
  `PASSWORD` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '密码，加密存储',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '配置，json结构',
  `USE_STS` int(0) NOT NULL COMMENT '使用状态，字典USEORNOT 1使用，0停用',
  `ONLINE_STS` int(0) NOT NULL COMMENT '在线状态，字典MDPDCONLINE 1在线，2异常，3离线',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` timestamp(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据源' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_source
-- ----------------------------
