-- ----------------------------
-- Table structure for sys_group
-- ----------------------------
DROP TABLE IF EXISTS `sys_group`;
CREATE TABLE `sys_group`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级分组ID',
  `NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '分组名称',
  `SN` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '分组编码',
  `LV_SN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '层级编码',
  `LV_NO` int(0) NOT NULL COMMENT '所在层级',
  `TYPES` int(0) NOT NULL COMMENT '分组类型，字典GROUPTYPES 1用户分组，9其他',
  `ICON_FONT` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '分组图标',
  `ICON_PIC` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '分组图片',
  `DESCS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '分组说明',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典 TUREORFALSE 1是，0否',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '分组状态，字典UGROUPSTATUS 1正常，2解散',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，0:正常,1:已删除',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN`(`SN`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE,
  INDEX `ORG_ID`(`ORG_ID`) USING BTREE,
  INDEX `PARENT_ID`(`PARENT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：分组，分组对应的行政区划信息直接存储在数据权限：行政区划权限表中。一个分组可以有多个行政区划，但都是当前用户所' ROW_FORMAT = Dynamic;

