-- Table structure for sys_group_member
-- ----------------------------
DROP TABLE IF EXISTS `sys_group_member`;
CREATE TABLE `sys_group_member`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `GROUP_ID` bigint(0) NOT NULL COMMENT '分组ID',
  `MB_TYPE` int(0) NOT NULL COMMENT '成员类型，字典GROUPTYPES 1用户分组，9其他',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '成员机构ID',
  `ORG_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员机构名称',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '成员ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员标题',
  `SN` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员编码',
  `TIME_JOIN` datetime(0) NULL DEFAULT NULL COMMENT '加入时间',
  `TIME_LEAVE` datetime(0) NULL DEFAULT NULL COMMENT '离开时间',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '成员状态，字典UGROUPMENSTATUS 1正常，2离开',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `DESCS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员描述',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，0:正常,1:已删除',
  `CREATED` timestamp(0) NULL DEFAULT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `GROUP_ID`(`GROUP_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：分组成员' ROW_FORMAT = Dynamic;

