CREATE TABLE `sys_logs`  (
  `ID` bigint(0) NOT NULL,
  `APP_SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '应用编码',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `USER_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '用户姓名',
  `ACTION_ID` bigint(0) NULL DEFAULT NULL COMMENT '业务操作ID',
  `REQUEST_ID` bigint(0) NULL DEFAULT NULL COMMENT '业务请求ID',
  `PREQUEST_ID` bigint(0) NULL DEFAULT NULL COMMENT '前置请求ID',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作标题',
  `CONTENTS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '操作内容',
  `TYPES` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作类别，字典LOGTYPE query查询，insert新增，update修改，delete删除,login登录，logout注销，resetpwd修改密码',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '操作状态，字典LOGSTATUS 1成功，2失败，3异常',
  `TARGET_ID` bigint(0) NULL DEFAULT NULL COMMENT '目标ID',
  `START_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '开始时间',
  `END_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '完成时间',
  `IP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '操作IP',
  `EXT_DATA` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '扩展信息，标准json对象存储{}',
  `ERROR_MESSAGE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '异常消息',
  `ERROR_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '异常代码',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `APP_SN`(`APP_SN`) USING BTREE,
  INDEX `TENANT_D`(`TENANT_ID`) USING BTREE,
  INDEX `RG_ID`(`ORG_ID`) USING BTREE,
  INDEX `USER_ID`(`USER_ID`) USING BTREE,
  INDEX `TITLE`(`TITLE`) USING BTREE,
  INDEX `TYPES`(`TYPES`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_logs
-- ----------------------------

-- ----------------------------
-- Table structure for sys_organ
-- ----------------------------
DROP TABLE IF EXISTS `sys_organ`;
CREATE TABLE `sys_organ`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `NAME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '企业/机构名称',
  `ALIAS` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '企业/机构别名',
  `TYPES` int(0) NULL DEFAULT NULL COMMENT '类型：字典ORGTYPES 1企业，2机构，3部门',
  `AREA_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '区域编码',
  `AREA_LABEL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '区域label，eg：广州市->天河区',
  `SN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '机构编码',
  `LV_SN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '层级编码',
  `LV_NO` int(0) NOT NULL COMMENT '所在层级',
  `BUSI_MAIN` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '主营业务',
  `BUSI_SCOP` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '经营范围',
  `ADDR` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '企业/机构地址',
  `TEL` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系电话',
  `LEVELS` int(0) NOT NULL COMMENT '级别',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点 1：是叶子节点 0：非叶子节点',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '状态',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN`(`SN`) USING BTREE,
  INDEX `PARENT_ID`(`PARENT_ID`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：机构信息' ROW_FORMAT = Dynamic;

