-- ----------------------------
-- Table structure for sys_page_his
-- ----------------------------
DROP TABLE IF EXISTS `sys_page_his`;
CREATE TABLE `sys_page_his`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `TMPL_ID` bigint(0) NULL DEFAULT NULL COMMENT '模版ID',
  `PAGE_ID` bigint(0) NOT NULL COMMENT '页面ID',
  `COMPONENT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '页面组件，字典SYSPAGECOMPONENT',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '页面标题',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '页面编码，唯一',
  `VERS` int(0) NOT NULL COMMENT '版本号',
  `SUMMARY` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '概要信息',
  `ICON` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '页面分类，字典PAGETYPE  code:编码型页面，setting：配置型页面，design：设计型页面',
  `TRADES` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行业分类，多个逗号分隔',
  `REVIEW_PIC` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '预览图片url',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '页面定义，json结构\r\n            ｛\r\n            \r\n            \r\n            ｝',
  `SIGNATURE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '页面签名，（configs等）字段hash运算后的值',
  `IS_TMPL` int(0) NOT NULL COMMENT '是否模版',
  `IS_GLOBAL` int(0) NOT NULL COMMENT '平台页面，字典TUREORFALSE 1是，0否',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '页面状态，字典PAGESTATUS 1新建，2发布，3修改，4撤回',
  `DESCS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：页面历史' ROW_FORMAT = Dynamic;

