-- ----------------------------
-- Table structure for sys_resource_api
-- ----------------------------
DROP TABLE IF EXISTS `sys_resource_api`;
CREATE TABLE `sys_resource_api`  (
  `ID` bigint(0) NOT NULL,
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `RES_ID` bigint(0) NOT NULL COMMENT '资源ID',
  `RES_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '资源类型，字典SYSRESTYPE menu：菜单，btn：按钮，tool：工具',
  `API_ID` bigint(0) NOT NULL COMMENT '接口ID',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`, `CREATED`, `CREATED_BY`, `LAST_UPDATED`, `LAST_UPDATED_BY`) USING BTREE,
  INDEX `APP_ID`(`APP_ID`) USING BTREE,
  INDEX `RESOURCE_ID`(`RES_ID`) USING BTREE,
  INDEX `API_ID`(`API_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：资源接口' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_resource_api
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '名称',
  `SN` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编码',
  `TYPES` int(0) NOT NULL COMMENT '类型，字典ROLETYPE 9其他',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN`(`SN`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE,
  INDEX `ORG_ID`(`ORG_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：角色信息' ROW_FORMAT = Dynamic;

