-- ----------------------------
-- Table structure for sys_tool
-- ----------------------------
DROP TABLE IF EXISTS `sys_tool`;
CREATE TABLE `sys_tool`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标题',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'URL',
  `IS_GLOBAL` int(0) NULL DEFAULT NULL COMMENT '是否全局（平台显示）',
  `IS_DEFUALT` int(0) NULL DEFAULT NULL COMMENT '是否默认（租户显示）',
  `IS_PRIVATE` int(0) NULL DEFAULT NULL COMMENT '是否私有',
  `TYPES` int(0) NULL DEFAULT NULL COMMENT '类型，字典TOOLTYPE  1应用，2工具',
  `ANSWER_WAY` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '响应方式，字典ANSWERWAY dialog对话框，drawer抽屉，router路由，page页面（浏览器新tab页）',
  `ICON` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配置，json格式存储',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：常用工具' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_tool
-- ----------------------------

-- ----------------------------
-- Table structure for sys_tool_mine
-- ----------------------------
DROP TABLE IF EXISTS `sys_tool_mine`;
CREATE TABLE `sys_tool_mine`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `TOOL_ID` bigint(0) NOT NULL COMMENT '工具ID',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配置，json格式存储',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：常用工具(我的)' ROW_FORMAT = Dynamic;

