-- Records of sys_tool_mine
-- ----------------------------

-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID，用户默认机构',
  `USER_TYPE` int(0) NOT NULL COMMENT '用户类型，字典USERTYPE 1管理员，2普通用户，9其他',
  `USERNAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '登录帐号',
  `PWD_TEXT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户密码',
  `PWD_SALT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '密码加密盐',
  `REAL_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '真实姓名',
  `ALIAS_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '别名',
  `AVATAR` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '头像',
  `BIRTHDAY` date NULL DEFAULT NULL COMMENT '生日，YYYY-MM-DD',
  `SEX` int(0) NULL DEFAULT NULL COMMENT '性别，字典SEX 1女，2男',
  `EMAIL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮箱',
  `QQ` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系qq',
  `TEL` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系电话',
  `SECURITY_QUESTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '密保问题',
  `SUCURITY_MFA` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'MFA设备标识',
  `LAST_LOGIN_TIME` datetime(0) NULL DEFAULT NULL COMMENT '上次登录时间',
  `LAST_LOGIN_IP` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '上次登录ip',
  `TOTAL_LOGIN_SUCCESS` bigint(0) NULL DEFAULT NULL COMMENT '累计成功登陆次数',
  `TOTAL_LOGIN_FAILUE` bigint(0) NULL DEFAULT NULL COMMENT '累计失败登陆次数',
  `STATUS` int(0) NOT NULL COMMENT '用户状态，字典USERSTATUS 1正常，2禁用，3注销，4锁定',
  `AUDIT_STS` int(0) NULL DEFAULT NULL COMMENT '审核状态，字典USERAUDITSTS 1待审核，2审核通过，3审核不通过',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，0:正常,1:已删除',
  `LOCK_TIME` datetime(0) NULL DEFAULT NULL COMMENT '锁定时间，锁定时间后才能继续登录',
  `DESCS` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNIQUE_USERNAME`(`USERNAME`) USING BTREE,
  UNIQUE INDEX `UNIQUE_TEL`(`TEL`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE,
  INDEX `ORG_ID`(`ORG_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：用户信息' ROW_FORMAT = Dynamic;

