-- ----------------------------
-- Table structure for ums_abs_group
-- ----------------------------
DROP TABLE IF EXISTS `ums_abs_group`;
CREATE TABLE `ums_abs_group`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `PARENT_ID` bigint(0) NULL DEFAULT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `FROM_TYPE` int(0) NULL DEFAULT NULL COMMENT '群组来源，字典 UMSABSGROUPFROM 1平台创建，2融合通讯',
  `FROM_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群组源ID（外部系统群组ID）',
  `TYPES` int(0) NOT NULL COMMENT '群类型，字典UMSABSGROUPTYPE  1我的群组，2公共群组，9其他',
  `NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群名称',
  `AREA_ID` bigint(0) NULL DEFAULT NULL COMMENT '行政区划ID',
  `AREA_SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行政区划编码',
  `AREA_NAME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行政区划名称',
  `LVSN` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '层级编码',
  `LEVEL` int(0) NULL DEFAULT NULL COMMENT '所在层级',
  `ICON` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群头像',
  `ICON_FONT` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群图标',
  `MASTER` bigint(0) NULL DEFAULT NULL COMMENT '群主',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群简介',
  `NOTICE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群公告',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '启用状态，字典USEORNOT 1使用，0停用',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否为叶子节点，TRUEORFALSE 1是，0否',
  `DEL_FLAG` int(0) NOT NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：通讯录-群组' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_abs_group
-- ----------------------------

-- ----------------------------
-- Table structure for ums_abs_menber
-- ----------------------------
DROP TABLE IF EXISTS `ums_abs_menber`;
CREATE TABLE `ums_abs_menber`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `GROUP_ID` bigint(0) NOT NULL COMMENT '群组ID',
  `PERSON_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `GROUP_TYPE` int(0) NOT NULL COMMENT '群类型，字典ABSGROUPTYPE  1我的群组，2公共群组，9其他',
  `POST_LABEL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群职务',
  `DUTY_LABEL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群职责',
  `REMARKS` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '群名备注',
  `USER_PORTRAIT` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员头像',
  `DESCS` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成员备注',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '启用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：通讯录-成员' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_abs_menber
-- ----------------------------

-- ----------------------------
-- Table structure for ums_abs_person
-- ----------------------------
DROP TABLE IF EXISTS `ums_abs_person`;
CREATE TABLE `ums_abs_person`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `FROM_TYPE` int(0) NOT NULL COMMENT '用户来源，字典 UMSABSGROUPFROM 1平台创建，2融合通讯',
  `FROM_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '用户源ID（外部系统用户ID）',
  `USER_TYPE` int(0) NOT NULL COMMENT '用户类型，字典UMSABSPERSONTYPE 1平台用户，99其他',
  `USER_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '姓名',
  `USER_PORTRAIT` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '头像',
  `ORG_NAME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '单位名称',
  `AREA_ID` bigint(0) NULL DEFAULT NULL COMMENT '行政区划ID',
  `AREA_SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行政区划编码',
  `AREA_NAME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行政区划名称',
  `UNIT_POSITION` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '工作单位职务',
  `ADMIN_POSITION` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '行政职务',
  `OFFICE_TEL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '办公电话',
  `MOBILE_TEL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '移动电话',
  `HOME_TEL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '住宅电话',
  `DUTY_TEL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '值班电话',
  `DTU` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '终端设备',
  `FMC` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '融合设备',
  `ADDR` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '通讯地址',
  `EMAIL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '电子邮箱',
  `FAX_NUM` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '传真',
  `ZIP_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮政编码',
  `DESCS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '用户备注',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '启用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：通讯录-用户' ROW_FORMAT = Dynamic;

