-- ----------------------------
-- Table structure for ums_message_status
-- ----------------------------
DROP TABLE IF EXISTS `ums_message_status`;
CREATE TABLE `ums_message_status`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `MESSAGE_ID` bigint(0) NOT NULL COMMENT '消息ID',
  `VIEW_STS` int(0) NULL DEFAULT 0 COMMENT '查阅状态，字典TUREORFALSE 1是，0否',
  `VIEW_TIME` datetime(0) NULL DEFAULT NULL COMMENT '查阅时间',
  `REPLY_INFO` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '回复内容',
  `CONFIRM_STATUS` int(0) NULL DEFAULT NULL COMMENT '消息确认状态 0:未确认 1:已确认',
  `CONFIRM_RESULT` int(0) NULL DEFAULT NULL COMMENT '确认结果,1：接收，2：拒绝',
  `CONFIRM_DATE` datetime(0) NULL DEFAULT NULL COMMENT '确认时间',
  `SEND_LOG` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '发送日志',
  `DEL_FLAG` int(0) NOT NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `TENANT_ID`, `MESSAGE_ID`, `USER_ID`, `VIEW_STS`, `CONFIRM_STATUS`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：消息状态' ROW_FORMAT = Dynamic;

