-- ----------------------------
-- Table structure for ums_message_target
-- ----------------------------
DROP TABLE IF EXISTS `ums_message_target`;
CREATE TABLE `ums_message_target`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `MESSAGE_ID` bigint(0) NOT NULL COMMENT '消息ID',
  `TARGET_TYPE` int(0) NOT NULL COMMENT '目标类型，字典UMSMSGTARGET 1：全局，2：租户，3：机构，4：用户，5：角色',
  `TARGET_ID` bigint(0) NOT NULL COMMENT '目标ID',
  `TARGET_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '目标名称',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`MESSAGE_ID`, `TARGET_TYPE`, `TARGET_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：消息对象' ROW_FORMAT = Dynamic;

