-- ----------------------------
-- Table structure for ums_sms_box
-- ----------------------------
DROP TABLE IF EXISTS `ums_sms_box`;
CREATE TABLE `ums_sms_box`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `GTW_ID` bigint(0) NOT NULL COMMENT '网关ID',
  `TMPL_ID` bigint(0) NULL DEFAULT NULL COMMENT '模版ID',
  `MESSAGE_ID` bigint(0) NULL DEFAULT NULL COMMENT '统一消息ID',
  `MSG_STS_ID` bigint(0) NULL DEFAULT NULL COMMENT '消息状态ID',
  `TODO_ID` bigint(0) NULL DEFAULT NULL COMMENT '待办消息ID',
  `REPLY_MSG_ID` bigint(0) NULL DEFAULT NULL COMMENT '回复消息ID',
  `PORTS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '端口号',
  `TEL` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '手机号',
  `TYPES` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类型，字典SMSBOXTYPE send：发送，receive：接收',
  `CONTENTS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '短信内容',
  `SEND_TIME` datetime(0) NULL DEFAULT NULL COMMENT '发送时间',
  `SEND_STS` int(0) NULL DEFAULT NULL COMMENT '发送状态，字典SMSSENDSTS 1待发送，2：发送成功，3发送失败',
  `SEND_LOG` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '发送日志',
  `VIEW_STS` int(0) NOT NULL COMMENT '查阅状态，字典SMSVIEWSTS 1未读，2已读，3已回',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFLASE 1是，0否',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `TENANT_ID`, `SEND_STS`) USING BTREE,
  INDEX `TEL`(`DEL_FLAG`, `TENANT_ID`, `TEL`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:短信箱' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_sms_box
-- ----------------------------

-- ----------------------------
-- Table structure for ums_sms_gtw
-- ----------------------------
DROP TABLE IF EXISTS `ums_sms_gtw`;
CREATE TABLE `ums_sms_gtw`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编码，唯一验证',
  `IP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '服务IP',
  `PORTS` int(0) NULL DEFAULT NULL COMMENT '服务端口',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '服务URL',
  `SEND_API` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发送接口',
  `SEND_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '发送脚本',
  `RECEIVE_API` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收信接口',
  `RECEIVE_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '收信脚本',
  `RECEIVE_CRON` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收信CRON',
  `RECEIPT_API` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '回执接口',
  `RECEIPT_SCRIPT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '回执脚本',
  `RECEIPT_CRON` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '回执CRON',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFLASE 1是，0否',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:短信网关' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_sms_gtw
-- ----------------------------

-- ----------------------------
-- Table structure for ums_tmpl
-- ----------------------------
DROP TABLE IF EXISTS `ums_tmpl`;
CREATE TABLE `ums_tmpl`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '模版分类，字典UMSTMPLTYPE workflow：工作流，other：其他',
  `TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '模版标题',
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '模版编码，唯一验证',
  `BODY_TEXT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '模版内容',
  `BODY_HTML` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '模版HTML',
  `VARS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '模版变量,json数组存储[{name,title,dataType,defaultValue}]',
  `USEL` int(0) NOT NULL COMMENT '使用级别，字典UMSTMPLUSEL 1：全局，2：租户，3：机构',
  `WAYS` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '通知方式，多个逗号分隔，默认站内信，字典UMSMESSAGEWAY sms：短信，email：邮件，site：站内信',
  `STATUS` int(0) NOT NULL COMMENT '模版状态，字典USEORNOT 1使用，0停用',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFLASE 1是，0否',
  `REMARK` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNI_SN`(`TENANT_ID`, `SN`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:模版，根据模版编码，通知方式自动发送各种消息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_tmpl
-- ----------------------------
INSERT INTO `ums_tmpl` VALUES (1949333473481510912, 100, 1901973435033374720, 10000, 'normal', '加班通知', 'jbtz', '{\"header\":[],\"main\":[{\"value\":\"准备加班冲刺吧！\"}],\"footer\":[]}', NULL, NULL, 1, 'site,sms', 1, 1, 0, NULL, '2025-07-27 12:58:12', 10000, '2025-07-27 12:58:12', 10000);

-- ----------------------------
-- Table structure for ums_todo
-- ----------------------------
DROP TABLE IF EXISTS `ums_todo`;
CREATE TABLE `ums_todo`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `CATEGORY_ID` bigint(0) NOT NULL COMMENT '分类ID',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `STATUS` int(0) NOT NULL DEFAULT 0 COMMENT '待办状态，字典UMSTODOSTS 1待处理，2处理中，3已超时，4已完成',
  `FROM_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源名称，字典UMSTODOFROM workflow：工作流',
  `BIZ_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务ID',
  `BIZ_PARAM` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务参数,eg:name=zs&sex=1',
  `VIEW_STS` int(0) NULL DEFAULT 0 COMMENT '查阅状态，字典TUREORFALSE 1是，0否',
  `VIEW_TIME` datetime(0) NULL DEFAULT NULL COMMENT '查阅时间',
  `PRIORITY` int(0) NULL DEFAULT NULL COMMENT '优先级，字典UMSTODOPRIORITY 1：一级，2：二级，3：三级，4：四级',
  `DEL_FLAG` int(0) NOT NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`TENANT_ID`, `DEL_FLAG`, `USER_ID`, `STATUS`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：用户待办表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_todo
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
